package com.medtrack.inventory.dto; import com.medtrack.inventory.entity.InventoryBalance; import java.util.UUID; public record InventoryBalanceResponse(UUID id,UUID warehouseId,UUID batchId,UUID storageLocationId,int availableQuantity,int reservedQuantity,int quarantinedQuantity,int physicalQuantity,long version){public static InventoryBalanceResponse of(InventoryBalance b){return new InventoryBalanceResponse(b.getId(),b.getWarehouse().getId(),b.getBatch().getId(),b.getStorageLocation().getId(),b.getAvailableQuantity(),b.getReservedQuantity(),b.getQuarantinedQuantity(),b.getPhysicalQuantity(),b.getVersion());}}
